INSERT INTO `cms_block` VALUES (20,20,1,2147483647,'Home Page Principal','home-page-principal','<div class=\"wrp-homepage-blocks\">\r\n<div class=\"wrp-vantagens\"><img src=\"{{media url=\"wysiwyg/Banners/minibanner2-edited_1.png\"}}\" width=\"1233\" height=\"35\" /></div>\r\n<div class=\"wrp-mini-banners\">\r\n<ul>\r\n<li><a href=\"https://loja.cozinhasitatiaia.com.br/cozinhas.html\"><img src=\"{{media url=\"wysiwyg/Banners/v2/banner_bloco_01.jpg\"}}\" width=\"635\" height=\"230\" /></a></li>\r\n<li><a href=\"https://loja.cozinhasitatiaia.com.br/cooktops.html\"><img src=\"{{media url=\"wysiwyg/Banners/v2/banner_bloco_02.jpg\"}}\" width=\"635\" height=\"230\" /></a></li>\r\n</ul>\r\n</div>\r\n<div class=\"wrp-homepage-blocks block-tbs\">{{block class=\"Magento\\\\Cms\\\\Block\\\\Block\" block_id=\"cozinhas_completas\"}}</div>\r\n<div class=\"home-products-list negative-margin-top\">\r\n<div class=\"wrp-title\"><span class=\"title\">Recomendados</span></div>\r\n{{widget type=\"Magento\\CatalogWidget\\Block\\Product\\ProductsList\" show_pager=\"0\" products_count=\"10\" template=\"Magento_CatalogWidget::product/widget/content/grid.phtml\" conditions_encoded=\"^[`1`:^[`type`:`Magento||CatalogWidget||Model||Rule||Condition||Combine`,`aggregator`:`all`,`value`:`1`,`new_child`:``^],`1--1`:^[`type`:`Magento||CatalogWidget||Model||Rule||Condition||Product`,`attribute`:`category_ids`,`operator`:`==`,`value`:`43, 44`^]^]\"}}</div>\r\n</div>','2018-11-21 19:10:07','2019-01-23 21:36:24',1),(21,21,1,2147483647,'Footer | Links','footer_links','<div class=\"wrp-footer-columns\">\r\n<div class=\"footer-logo\"><img src=\"{{media url=\"wysiwyg/logo-ftr.png\"}}\" alt=\"\" /></div>\r\n<div class=\"footer-column\">\r\n<p class=\"text\"><strong>Itatiaia Móveis S/A</strong></p>\r\n<ul class=\"store-info\">\r\n<li class=\"phone\">\r\n<p>(31) 3197-0918</p>\r\n</li>\r\n<li class=\"address\">\r\n<p>Razão Social: Itatiaia Móveis S/A<br />CNPJ: 25.331.521/0012-05<br />Endereço: Alameda Oscar Niemeyer<br />Número: 119  9° andar  <br />CEP: <span>34006-056</span></p>\r\n</li>\r\n</ul>\r\n</div>\r\n<div class=\"footer-column second\"><span class=\"title\">Institucional</span>\r\n<ul class=\"list-links\">\r\n<li class=\"nav item\"><a href=\"/sobre-nos\">Sobre nós</a></li>\r\n<li class=\"nav item\"><a href=\"https://atendimento.cozinhasitatiaia.com.br\" target=\"_blank\">Fale conosco</a></li>\r\n</ul>\r\n</div>\r\n<div class=\"footer-column third\"><span class=\"title\">Ajuda</span>\r\n<ul class=\"list-links\">\r\n<li class=\"nav item\"><a href=\"/sales/order/history\">Meus Pedidos</a></li>\r\n<li class=\"nav item\"><a href=\"https://atendimento.cozinhasitatiaia.com.br\">Perguntas Frequentes</a></li>\r\n<li class=\"nav item\"><a href=\"/politica-de-devolucoes\">Política de Devoluções</a></li>\r\n<li class=\"nav item\"><a href=\"/politica-de-entrega\">Política de Entrega</a></li>\r\n<li class=\"nav item\"><a href=\"/termo-de-uso-e-condicoes\">Termos de Uso e Condições</a></li>\r\n<li class=\"nav item\"><a href=\"/politicas-de-privacidade-e-seguranca\">Políticas de Privacidade e Segurança</a></li>\r\n</ul>\r\n</div>\r\n<div class=\"wrp-social-links\">\r\n<ul class=\"social-links\">\r\n<li><a class=\"facebook\" title=\"Facebook\" href=\"https://www.facebook.com/CozinhasItatiaia/\" target=\"_blank\"><span>Facebook</span></a></li>\r\n<li><a class=\"twitter\" title=\"Twitter\" href=\"https://twitter.com/itatiaiamoveis\" target=\"_blank\"><span>Twitter</span></a></li>\r\n<li><a class=\"youtube\" title=\"YouTube\" href=\"https://www.youtube.com/user/cozinhaitatiaia\" target=\"_blank\"><span>Youtube</span></a></li>\r\n</ul>\r\n</div>\r\n</div>','2018-11-21 19:11:24','2019-01-22 00:16:09',1),(22,22,1,2147483647,'Footer | Newsletter','footer_news','<div class=\"wrp-news\">\r\n<div class=\"wrp-content-news\">\r\n<div class=\"wrp-title\">\r\n<div class=\"title\">\r\n<p>Inscreva-se na nossa newsletter</p>\r\n</div>\r\n</div>\r\n{{block class=\"Magento\\Newsletter\\Block\\Subscribe\" name=\"home.form.subscribe\" template=\"Magento_Newsletter::subscribe.phtml\"}}\r\n<div class=\"subtitle\">\r\n<p>Cadastre seu e-mail e saiba tudo em primeira mão!</p>\r\n<div></div>\r\n<div class=\"inpts\"></div>\r\n</div>\r\n</div>\r\n</div>','2018-11-21 19:11:55','2019-01-03 16:48:35',1),(23,23,1,2147483647,'Footer | Formas de Pagamento','footer_formas_pagamento','<div class=\"wrp-formas-pagamento\"><img src=\"{{media url=\"wysiwyg/geral/formas-pagamento.png\"}}\" alt=\"\" /></div>','2018-11-21 19:12:26','2018-11-21 19:12:26',1),(24,24,1,2147483647,'Checkout Header | Informações','checkout_header_infos','<div class=\"infos\">\r\n<p>Você está em um ambiente seguro para finalizar a sua compra. <br />Em caso de dúvida, entre em contato <span>(31) 3197-0918</span></p>\r\n</div>','2018-11-21 19:13:33','2019-01-03 17:06:37',1),(25,25,1,2147483647,'Central de Atendimento','atendimento','<p><a href=\"https://atendimento.cozinhasitatiaia.com.br\" target=\"_blank\">Central<br />de Atendimento</a></p>','2018-11-21 19:14:46','2019-01-03 16:46:24',1),(26,26,1,2147483647,'Cozinhas Completas | Desktop','cozinhas_completas','<div class=\"home-products-list\">\r\n<div class=\"wrp-title\"><span class=\"title\">Cozinhas Completas</span></div>\r\n<div id=\"tabs-list\">\r\n<ul class=\"nav nav-tabs\">\r\n<li class=\"active\"><a href=\"#tab1\">Cozinhas de aço</a></li>\r\n<li><a href=\"#tab2\">Cozinhas de madeira</a></li>\r\n</ul>\r\n<div class=\"wrp-tabs-out\">\r\n<div class=\"wrp-tabs-in\"><section id=\"tab1\" class=\"tab-content active\">{{widget type=\"Magento\\CatalogWidget\\Block\\Product\\ProductsList\" show_pager=\"0\" products_count=\"10\" template=\"Magento_CatalogWidget::product/widget/content/grid.phtml\" conditions_encoded=\"^[`1`:^[`type`:`Magento||CatalogWidget||Model||Rule||Condition||Combine`,`aggregator`:`all`,`value`:`1`,`new_child`:``^],`1--1`:^[`type`:`Magento||CatalogWidget||Model||Rule||Condition||Product`,`attribute`:`category_ids`,`operator`:`==`,`valu