INSERT INTO `email_template` VALUES (1,'Nova conta de cliente','{{template config_path=\"design/email/header_template\"}}\r\n\r\n<p class=\"greeting\">{{trans \"%name,\" name=$customer.name}}</p>\r\n<p>{{trans \"Bem vindo à %store_name.\" store_name=$store.getFrontendName()}}</p>\r\n<p>\r\n    {{trans\r\n        \'Para fazer seu login durante o seu pedido ou no <a href=\"%customer_url\">paine da sua conta</a>:\'\r\n\r\n        customer_url=$this.getUrl($store,\'customer/account/\',[_nosid:1])\r\n    |raw}}\r\n</p>\r\n<ul>\r\n    <li><strong>{{trans \"E-mail:\"}}</strong> {{var customer.email}}</li>\r\n    <li><strong>{{trans \"Senha:\"}}</strong> <em>{{trans \"Senha criada durante o seu cadastro\"}}</em></li>\r\n</ul>\r\n<p>\r\n    {{trans\r\n        \'Esqueceu sua senha? Clique <a href=\"%reset_url\">aqui</a> para criar uma nova senha.\'\r\n\r\n        reset_url=\"$this.getUrl($store,\'customer/account/createPassword/\',[_query:[id:$customer.id,token:$customer.rp_token],_nosid:1])\"\r\n    |raw}}\r\n</p>\r\n<p>{{trans \"Fazendo login em sua conta, você pode:\"}}</p>\r\n<ul>\r\n    <li>{{trans \"Realizar pedidos mais rapidamente\"}}</li>\r\n    <li>{{trans \"Acompanhar o status do seus pedidos realizados\"}}</li>\r\n    <li>{{trans \"Editar suas informações da conta\"}}</li>\r\n    <li>{{trans \"Gerenciar sua lista de desejos\"}}</li>\r\n</ul>\r\n\r\n{{template config_path=\"design/email/footer_template\"}}',NULL,2,'Bem vindo &agrave; Loja oficial Cozinhas Itatiaia',NULL,NULL,'2019-01-18 01:59:48','2019-01-18 02:00:12','customer_create_account_email_template','{\"var this.getUrl($store, \'customer/account/\')\":\"Customer Account URL\",\"var customer.email\":\"Customer Email\",\"var customer.name\":\"Customer Name\"}'),(2,'Rodapé e-mails','<!-- End Content -->\r\n                    </td>\r\n                </tr>\r\n                <tr>\r\n                    <td class=\"footer\">\r\n                        <p class=\"closing\">{{trans \"%store_name\" store_name=$store.getFrontendName()}}</p>\r\n                    </td>\r\n                </tr>\r\n            </table>\r\n        </td>\r\n    </tr>\r\n</table>\r\n<!-- End wrapper table -->\r\n</body>',NULL,2,'Rodap&eacute;',NULL,NULL,'2019-01-18 02:00:58','2019-01-18 02:01:15','design_email_footer_template','{\"var store.getFrontendName()\":\"Store Name\"}'),(3,'Alteração de e-mail na conta de cliente','{{template config_path=\"design/email/header_template\"}}\r\n\r\n<p class=\"greeting\">{{trans \"Olá,\"}}</p>\r\n<br>\r\n\r\n<p>\r\n    {{trans \"Nós recebemos uma solicitação para atualização do endereço de e-mail associado à sua conta.\" store_name=$store.getFrontendName()}}<br>\r\nSe você não autorizou esta ação, contate-nos imediatamente em <a href=\"https://atendimento.cozinhasitatiaia.com.br\">nosso canal de atendimento</a>.\r\n</p>\r\n<br>\r\n\r\n{{template config_path=\"design/email/footer_template\"}}',NULL,2,'Seu e-mail foi alterado',NULL,NULL,'2019-01-18 02:02:24','2019-01-18 02:02:24','customer_account_information_change_email_template','{}'),(4,'Alteração de e-mail e senha na conta de cliente','{{template config_path=\"design/email/header_template\"}}\r\n\r\n<p class=\"greeting\">{{trans \"Olá,\"}}</p>\r\n<br>\r\n\r\n<p>\r\n   Nós recebemos uma solicitação para alteração da sua conta de e-mail e senha.<br>\r\n  Se você não autorizou esta ação, entre em contato conosco em <a href=\"https://atendimento.cozinhasitatiaia.com.br\">nossa central de atendimento</a>.\r\n</p>\r\n<br>\r\n\r\n{{template config_path=\"design/email/footer_template\"}}',NULL,2,'Seu e-mail e senha foram alterados',NULL,NULL,'2019-01-18 02:03:05','2019-01-18 02:03:05','customer_account_information_change_email_and_password_template','{}'),(5,'Alteração de senha','{{template config_path=\"design/email/header_template\"}}\r\n\r\n<p class=\"greeting\">{{trans \"%name,\" name=$customer.name}}</p>\r\n<p>{{trans \"Recebemos sua solicitação de alteração de senha\"}}</p>\r\n<p>{{trans \"Clique no link abaixo para continuar:\"}}</p>\r\n\r\n<table class=\"button\" width=\"100%\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\r\n    <tr>\r\n        <td>\r\n            <table class=\"inner-wrapper\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" align=\"center\">\r\n                <tr>\r\n                    <td align=\"center\">\r\n                        <a href=\"{{var this.getUrl($store,\'customer/account/createPassword/\',[_query:[token:$customer.rp_token],_nosid:1])}}\" target=\"_blank\">{{trans \"Gerar uma nova senha\"}}</a>\r\n                    </td>\r\n                </tr>\r\n            </table>\r\n        </td>\r\n    </tr>\r\n</table>\r\n\r\n<p>{{trans \"Se você não solicitou a alteração de sua senha, por favor, ignore este e-mail.\"}}</p>\r\n\r\n{{template config_path=\"design/email/footer_template\"}}',NULL,2,'Altera&ccedil;&atilde;o de senha de acesso',NULL,NULL,'2019-01-18 02:04:52','2019-01-18 02:06:27','customer_password_forgot_email_template','{\"var customer.name\":\"Customer Name\",\"var this.getUrl($store, \'customer/account/createPassword/\', [_query:[id:$customer.id, token:$customer.rp_token]])\":\"Reset Password URL\"}'),(6,'Senha atualizada','{{template config_path=\"design/email/header_template\"}}\r\n\r\n<p class=\"greeting\">{{trans \"Olá,\"}}</p>\r\n<br>\r\n\r\n<p>\r\n   Recebemos sua solicitação para atualização de senha.<br>\r\n  Se você não autorizou esta ação, por favor, entre em contato conosco em <a href=\"#\">nossa central de atendimento</a>.\r\n</p>\r\n<br>\r\n\r\n{{template config_path=\"design/email/footer_template\"}}',NULL,2,'Sua senha foi atualizada',NULL,NULL,'2019-01-18 02:05:47','2019-01-18 02:05:47','customer_password_reset_password_template','{\"var customer.name\":\"Customer Name\"}'),(7,'Lembrete de alteração de senha','{{template config_path=\"design/email/header_template\"}}\r\n\r\n<p class=\"greeting\">{{trans \"%name,\" name=$customer.name}}</p>\r\n<p>Recebemos sua solicitação para alteração de senha.</p>\r\n<p>Para continuar, clique no link abaixo:</p>\r\n\r\n<table class=\"button\" width=\"100%\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\r\n    <tr>\r\n        <td>\r\n            <table class=\"inner-wrapper\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\" align=\"center\">\r\n                <tr>\r\n                    <td align=\"center\">\r\n                        <a href=\"{{var this.getUrl($store,\'customer/account/createPassword\',[_query:[id:$customer.id,token:$customer.rp_token],_nosid:1])}}\" target=\"_blank\">{{trans \"Gerar uma nova senha\"}}</a>\r\n                    </td>\r\n                </tr>\r\n            </table>\r\n        </td>\r\n    </tr>\r\n</table>\r\n\r\n<p>Se você não solicitou a alteração de sua senha, por favor, ignore este e-mail.</p>\r\n\r\n{{template config_path=\"design/email/footer_template\"}}',NULL,2,'Altera&ccedil;&atilde;o de senha',NULL,NULL,'2019-01-18 02:07:20','2019-01-18 02:07:20','customer_password_remind_email_template','{\"var this.getUrl(store, \'customer/account/\')\":\"Customer Account URL\",\"var customer.name\":\"Customer Name\"}'),(8,'Confirmação de inscrição na news','{{template config_path=\"design/email/header_template\"}}\r\n\r\n<p class=\"greeting\">{{trans \"Obrigado por assinar nossa newsletter.\"}}</p>\r\n<p>{{trans \"Para confirmar sua inscrição, por favor, clique no link abaixo:\"}}</p>\r\n<p><a href=\"{{var subscriber.getConfirmationLink()}}\">{{var subscriber.getConfirmationLink()}}</a></p>\r\n\r\n{{template config_path=\"design/email/footer_template\"}}',NULL,2,'Confirma&ccedil;&atilde;o de inscri&ccedil;&atilde;o do seu e-mail',NULL,NULL,'2019-01-18 02:08:11','2019-01-18 02:08:11','newsletter_subscription_confirm_email_template','{\"var customer.name\":\"Customer Name\",\"var subscriber.getConfirmationLink()\":\"Subscriber Confirmation URL\"}'),(9,'Inscrição confirmada na newsletter','{{template config_path=\"design/email/header_template\"}}\r\n\r\n{{trans \"Obrigado! Confirmamos sua inscrição em nossa newsletter e a partir de agora você receberá nossas novidades por e-mail.\"}}\r\n\r\n{{template config_path=\"design/email/footer_template\"}}',NULL,2,'Inscri&ccedil;&atilde;o confirmada em nossa newsletter',NULL,NULL,'2019-01-18 02:08:56','2019-01-18 02:08:56','newsletter_subscription_success_email_template','{\"template config_path=\\\"design\\/email\\/footer_template\\\"\":\"Email Footer Template\",\"template config_path=\\\"design\\/email\\/header_template\\\"\":\"Email Header Template\"}'),(10,'Desinscrição na news','{{template config_path=\"design/email/header_template\"}}\r\n\r\n{{trans \"Este é um e-mail de confirmação para sua desinscrição em nossa newsletter.\"}}\r\n\r\n{{template config_path=\"design/email/footer_template\"}}',NULL,2,'Desinscri&ccedil;&atilde;o em nossa newsletter',NULL,NULL,'2019-01-18 02:09:37','2019-01-18 02:11:52','newsletter_subscription_un_email_template','{\"template config_path=\\\"design\\/email\\/footer_template\\\"\":\"Email Footer Template\",\"template config_path=\\\"design\\/email\\/header_template\\\"\":\"Email Header Template\"}'),(11,'Novo pedido','{{template config_path=\"design/email/header_template\"}}\r\n\r\n<table>\r\n    <tr class=\"email-intro\">\r\n        <td>\r\n            <p>\r\n<strong>Obrigado por comprar na Itatiaia!</strong>\r\n</p>\r\n<p>\r\nPara compras com cartão de crédito, a confirmação do pagamento pode levar até 2 dias, dependendo da sua operadora. Porém, normalmente, acontece em até 2 horas.\r\n</p>\r\n<p>\r\nPara compras com boleto, iremos aguardar a confirmação do pagamento enviado pelo banco para iniciarmos os processos internos.\r\n</p>\r\n            <p>\r\nSe você tiver dúvidas sobre seu pedido, contate-nos em <a href=\"https://atendimento.cozinhasitatiaia.com.br\">nossa central de atendimento</a>.\r\n            </p>\r\n        </td>\r\n    </tr>\r\n    <tr class=\"email-summary\">\r\n        <td>\r\n            <h1>{{trans \'Pedido <span class=\"no-link\">#%increment_id</span>\' increment_id=$order.increment_id |raw}}</h1>\r\n            <p>{{trans \'Realizado em <span class=\"no-link\">%created_at</span>\' created_at=$order.getCreatedAtFormatted(2) |raw}}</p>\r\n        </td>\r\n    </tr>\r\n    <tr class=\"email-information\">\r\n        <td>\r\n            <table class=\"order-details\">\r\n                <tr>\r\n                    <td class=\"address-details\">\r\n                        <h3>{{trans \"Endereço de cobrança\"}}</h3>\r\n                        <p>{{var formattedBillingAddress|raw}}</p>\r\n                    </td>\r\n                    {{depend order.getIsNotVirtual()}}\r\n                    <td class=\"address-details\">\r\n                        <h3>{{trans \"Endereço de entrega\"}}</h3>\r\n                        <p>{{var formattedShippingAddress|raw}}</p>\r\n                    </td>\r\n                    {{/depend}}\r\n                </tr>\r\n                <tr>\r\n                    <td class=\"method-info\">\r\n                        <h3>{{trans \"Método de pagamento\"}}</h3>\r\n                        {{var payment_html|raw}}\r\n                    </td>\r\n                    {{depend order.getIsNotVirtual()}}\r\n                    <td class=\"method-info\">\r\n                        <h3>{{trans \"Método de entrega\"}}</h3>\r\n                        <p>{{var order.getShippingDescription()}}</p>\r\n                        {{if shipping_msg}}\r\n                        <p>{{var shipping_msg}}</p>\r\n                        {{/if}}\r\n                    </td>\r\n                    {{/depend}}\r\n                </tr>\r\n            </table>\r\n            {{layout handle=\"sales_email_order_items\" order=$order area=\"frontend\"}}\r\n        </td>\r\n    </tr>\r\n</table>\r\n\r\n{{template config_path=\"design/email/footer_template\"}}',NULL,2,'{{trans \"Pedido #%increment_id recebido! Cozinhas Itatiaia\" increment_id=$order.increment_id | raw}}',NULL,NULL,'2019-01-18 02:10:20','2019-01-18 02:10:20','sales_email_order_template','{\"var formattedBillingAddress|raw\":\"Billing Address\",\"var order.getEmailCustomerNote()\":\"Email Order Note\",\"var order.increment_id\":\"Order Id\",\"layout handle=\\\"sales_email_order_items\\\" order=$order area=\\\"frontend\\\"\":\"Order Items Grid\",\"var payment_html|raw\":\"Payment Details\",\"var formattedShippingAddress|raw\":\"Shipping Address\",\"var order.getShippingDescription()\":\"Shipping Description\",\"var shipping_msg\":\"Shipping message\"}'),(12,'Confirmação do pagamento','{{template config_path=\"design/email/header_template\"}}\r\n\r\n<table>\r\n    <tr class=\"email-intro\">\r\n        <td>\r\n            <p class=\"greeting\">{{trans \"%name,\" name=$order.getCustomerName()}}</p>\r\n            <p>\r\nSeu pagamento foi confirmado. Já estamos separando e embalando seus produtos.<br><br>\r\n\r\nO preparo do seu pedido pode demorar até 48h, mas normalmente é finalizado em 24h úteis.\r\n            </p>\r\n        </td>\r\n    </tr>\r\n    <tr class=\"email-information\">\r\n        <td>\r\n            {{depend comment}}\r\n            <table class=\"message-info\">\r\n                <tr>\r\n                    <td>\r\n                        {{var comment|escape|nl2br}}\r\n                    </td>\r\n                </tr>\r\n            </table>\r\n            {{/depend}}\r\n            <table class=\"order-details\">\r\n                <tr>\r\n                    <td class=\"address-details\">\r\n                        <h3>{{trans \"Endereço de cobrança\"}}</h3>\r\n                        <p>{{var formattedBillingAddress|raw}}</p>\r\n                    </td>\r\n                    {{depend order.getIsNotVirtual()}}\r\n                    <td class=\"address-details\">\r\n                        <h3>{{trans \"Endereço de entrega\"}}</h3>\r\n                        <p>{{var formattedShippingAddress|raw}}</p>\r\n                    </td>\r\n                    {{/depend}}\r\n                </tr>\r\n                <tr>\r\n                    <td class=\"method-info\">\r\n                        <h3>{{trans \"Método de pagamento\"}}</h3>\r\n                        {{var payment_html|raw}}\r\n                    </td>\r\n                    {{depend order.getIsNotVirtual()}}\r\n                    <td class=\"method-info\">\r\n                        <h3>{{trans \"Método de entrega\"}}</h3>\r\n                        <p>{{var order.getShippingDescription()}}</p>\r\n                    </td>\r\n                    {{/depend}}\r\n                </tr>\r\n            </table>\r\n            {{layout area=\"frontend\" handle=\"sales_email_order_invoice_items\" invoice=$invoice order=$order}}\r\n        </td>\r\n    </tr>\r\n</table>\r\n\r\n{{template config_path=\"design/email/footer_template\"}}',NULL,2,'Confirma&ccedil;&atilde;o do pagamento do seu pedido #{{var order.increment_id}}',NULL,NULL,'2019-01-18 02:11:14','2019-01-18 02:11:14',NULL,NULL),(13,'Atualização do status do pedido','{{template config_path=\"design/email/header_template\"}}\r\n\r\n<table>\r\n    <tr class=\"email-intro\">\r\n        <td>\r\n            <p class=\"greeting\">{{trans \"%name,\" name=$order.getCustomerName()}}</p>\r\n            <p>\r\n                {{trans\r\n                    \"Seu pedido #%increment_id foi atualizado para <strong>%order_status</strong>.\"\r\n\r\n                    increment_id=$order.increment_id\r\n                    order_status=$order.getStatusLabel()\r\n                |raw}}\r\n            </p>\r\n        </td>\r\n    </tr>\r\n    <tr class=\"email-information\">\r\n        <td>\r\n            <table class=\"message-info\">\r\n                <tr>\r\n                    <td>\r\n{{block class=\'Magento\\\\Framework\\\\View\\\\Element\\\\Template\' area=\'frontend\' template=\'Magento_Sales::email/pedido_faturado.phtml\' order=$order}}\r\n                    </td>\r\n                </tr>\r\n            </table>\r\n        </td>\r\n    </tr>\r\n    <tr class=\"email-information\">\r\n        <td>\r\n            {{depend comment}}\r\n            <table class=\"message-info\">\r\n                <tr>\r\n                    <td>\r\n                        {{var comment|escape|nl2br}}\r\n                    </td>\r\n                </tr>\r\n            </table>\r\n            {{/depend}}\r\n        </td>\r\n    </tr>\r\n</table>\r\n\r\n{{template config_path=\"design/email/footer_template\"}}',NULL,2,'Atualiza&ccedil;&atilde;o do seu pedido #{{var order.increment_id}}',NULL,NULL,'2019-01-18 02:12:44','2019-01-18 02:12:44','sales_email_order_comment_template','{\"var this.getUrl($store, \'customer/account/\')\":\"Customer Account URL\",\"var order.getCustomerName()\":\"Customer Name\",\"var comment\":\"Order Comment\",\"var order.increment_id\":\"Order Id\",\"var order.getStatusLabel()\":\"Order Status\"}');
