INSERT INTO `magento_customersegment_segment` VALUES (1,'Clientes premium',NULL,1,'{\"type\":\"Magento\\\\CustomerSegment\\\\Model\\\\Segment\\\\Condition\\\\Combine\\\\Root\",\"attribute\":null,\"operator\":null,\"value\":\"1\",\"is_value_processed\":null,\"aggregator\":\"all\",\"conditions\":[{\"type\":\"Magento\\\\CustomerSegment\\\\Model\\\\Segment\\\\Condition\\\\Sales\\\\Salesamount\",\"attribute\":\"total\",\"operator\":\">=\",\"value\":\"1\",\"is_value_processed\":null,\"aggregator\":\"all\",\"conditions\":[{\"type\":\"Magento\\\\CustomerSegment\\\\Model\\\\Segment\\\\Condition\\\\Order\\\\Status\",\"attribute\":false,\"operator\":\"==\",\"value\":\"processing\",\"is_value_processed\":false},{\"type\":\"Magento\\\\CustomerSegment\\\\Model\\\\Segment\\\\Condition\\\\Uptodate\",\"attribute\":false,\"operator\":\"<=\",\"value\":\"30\",\"is_value_processed\":false},{\"type\":\"Magento\\\\CustomerSegment\\\\Model\\\\Segment\\\\Condition\\\\Order\\\\Status\",\"attribute\":false,\"operator\":\"==\",\"value\":\"complete\",\"is_value_processed\":false}]}]}',1,'SELECT 1 FROM `customer_entity` AS `root` WHERE ((IF((SELECT IF(IF(SUM(sales_order.base_grand_total) IS NOT NULL, SUM(sales_order.base_grand_total), 0) >= 1, 1, 0) FROM `sales_order`\n INNER JOIN `store` ON sales_order.store_id=store.store_id WHERE (store.website_id IN (:website_id)) AND (sales_order.customer_id = :customer_id) AND (sales_order.status = \'processing\' AND sales_order.created_at <= \'2018-10-29\' AND sales_order.status = \'complete\')), 1, 0) = 1))',1);
/*!40000 ALTER TABLE `magento_customersegment_segment` ENABLE KEYS */;
UNLOCK TABLES;

