  `original_data` text COMMENT 'Logged Original Data',
  `result_data` text COMMENT 'Logged Result Data',
  PRIMARY KEY (`id`),
  KEY `MAGENTO_LOGGING_EVENT_CHANGES_EVENT_ID` (`event_id`),
